insert into public.products (slug, ref, name, collection, edition, price, image, segment, shape, lens_color, lens_type, material, polarized, caliber, bridge, temple, weight, sustainability_badge, description, craft_note, coordinates, stock, active, sort_order) values
  ('brisa-costera', 'MR-01', 'Brisa', 'Urban', 'Serie 01 // Brisa & Acero', 1899, '/images/catalogo/brisa-costera.jpg', 'unisex', 'Geométrico Rectangular', 'Obsidiana Humo al Atardecer', 'Polarizado HD Filtro Cat. 3', 'Acero Quirúrgico 316L Cepillado & Bio-Acetato', true, 54, 18, 145, 28, '100% Acero Reciclable', 'Inspirada en la pureza del aire costero y las líneas limpias de la arquitectura moderna. Estructura frontal monolítica con tratamiento cepillado y micas polarizadas para neutralizar el resplandor de la costa y los cristales al atardecer.', 'Soldadura micrométrica alemana y almohadillas nasales de elastómero médico hipoalergénico que evitan desplazamientos con el calor.', '19.4195° N, 99.1618° W // Taller Central', 10, true, 1),
  ('duna-ambar', 'MR-02', 'Duna', 'Nature', 'Serie 02 // Carey & Arena', 2199, '/images/catalogo/duna-ambar.jpg', 'women', 'Arco Esculpido Circular', 'Ámbar Miel Mineral', 'Cristal Mineral de Alta Densidad', 'Bio-Acetato de Algodón 8mm', false, 51, 21, 142, 34, 'Bio-Acetato 100% Biodegradable', 'Curvas orgánicas inspiradas en las ondulaciones de las dunas al caer la tarde. Bloque grueso de acetato vegetal pulido en seco durante 72 horas para lograr una calidez táctil inigualable.', 'Bisel interior aligerado para reducir el peso en el tabique nasal manteniendo la presencia visual frontal.', '23.2494° N, 106.4111° W // Mazatlán Costa', 10, true, 2),
  ('marea-marina', 'MR-03', 'Marea', 'rePlastic', 'Serie 03 // Océano Circular', 1699, '/images/catalogo/marea-marina.jpg', 'unisex', 'Panto Contemporáneo', 'Verde Salvia Profundo', 'Mica Polimérica Polarizada HD', 'rePlastic® Marino Circular', true, 49, 20, 145, 21, '0% Plástico Virgen', 'Moldeada a partir de redes de pesca recuperadas del mar y polímeros post-consumo regenerados. Ultraligera y con memoria elástica para acompañarte en tus viajes sin deformarse.', 'Pigmentación en masa sin disolventes químicos agresivos. Superficie mate de tacto suave.', '24.1426° N, 110.3128° W // Mar de Cortés', 10, true, 3),
  ('ocaso-solar', 'MR-04', 'Ocaso', 'Horizon', 'Serie 04 // Cobre & Atardecer', 2399, '/images/catalogo/ocaso-solar.jpg', 'unisex', 'Doble Puente Aviador', 'Azul Ocaso Polarizado', 'Mica Polarizada con Capa Hidrofóbica', 'Cobre & Titanio Grado Aeroespacial', true, 58, 15, 140, 24, 'Titanio Forjado Durable', 'Reinterpretación geométrica de la silueta aviador. Chasis en aleación de titanio y cobre pulido con doble puente tensor y micas preparadas para navegar a contraluz.', 'Bisagras de flexión integrada con muelle interno de acero inoxidable que no se vencen con el uso diario.', '20.6534° N, 105.2253° W // Puerto Vallarta', 10, true, 4),
  ('sierra-mineral', 'MR-05', 'Sierra', 'Urban', 'Serie 01 // Piedra & Mineral', 2299, '/images/catalogo/sierra-mineral.jpg', 'men', 'Cuadrado Grueso', 'Castaño Cálido Antirreflejo', 'Cristal Mineral Templado Cat. 3', 'Bio-Acetato Densificado & Alma de Titanio', false, 53, 19, 148, 38, 'Varilla con Alma de Acero Quirúrgico', 'Un diseño contundente y geométrico inspirado en las formaciones rocosas de la sierra. El alma metálica interior queda a la vista a través del acetato ahumado con grabados de precisión.', 'Bisagras con 7 dientes de engranaje remachadas al chasis con pasadores pasantes pulidos a ras.', '25.6866° N, 100.3161° W // Sierra Madre', 10, true, 5),
  ('alba-cuarzo', 'MR-06', 'Alba', 'Nature', 'Serie 02 // Cuarzo & Primera Luz', 2199, '/images/catalogo/alba-cuarzo.jpg', 'women', 'Cat-Eye Geométrico', 'Rosa Cuarzo al Atardecer', 'Mineral Cat. 3 UV400', 'Bio-Acetato Rosa Ahumado & Latón', false, 52, 17, 142, 31, 'Bio-Acetato de Algodón Cured', 'Inspirada en el instante en que amanece sobre la costa. Silueta cat-eye esculpida con facetas afiladas y filtro en tono rosa cuarzo que realza la calidez de la luz natural y protege 100% de la radiación UV.', 'Acabado pulido a mano con cera de carnauba orgánica para un tacto sedoso y brillante que no se raya.', '20.9674° N, 89.5926° W // Península', 10, true, 6)
